-- À exécuter UNE FOIS si schema.sql et seed.sql ont déjà été lancés (version précédente). Ne supprime aucune donnée de travail.

create table if not exists public.ref_content (
  key text primary key, value jsonb not null, updated_at timestamptz not null default now()
);
alter table public.ref_content enable row level security;
drop policy if exists ref_content_read on public.ref_content;
create policy ref_content_read on public.ref_content for select to authenticated using (true);

alter table public.brouillons add column if not exists position int not null default 0;
update public.brouillons set position = case id when 'manager' then 0 when 'it' then 1 when 'sg' then 2 else position end;

drop function if exists public.set_demo_role(text, text);
-- Mode démonstration : session anonyme Supabase, profil choisi depuis l'écran de connexion.
-- Réservé aux sessions anonymes : un vrai compte ne peut pas changer son profil par ce biais.
create or replace function public.set_demo_role(r text) returns void
language plpgsql security definer set search_path = public as $$
begin
  if coalesce((auth.jwt()->>'is_anonymous')::boolean, false) is not true then
    raise exception 'Réservé au mode démonstration';
  end if;
  if r not in ('collab','manager','hrbp','dir') then raise exception 'Profil inconnu'; end if;
  update public.profiles
     set role = r,
         full_name = coalesce((select value -> r ->> 0 from public.ref_content where key = 'ident'), full_name)
   where id = auth.uid();
end $$;
revoke all on function public.set_demo_role(text) from public, anon;
grant execute on function public.set_demo_role(text) to authenticated;


-- Contenus de référence
insert into public.ref_content (key,value) values
('sources','{"mail":{"label":"Boîte RH","cls":"b-violet"},"cr":{"label":"Compte rendu","cls":"b-sky"}}'::jsonb),
('reponses','[{"id":"reglage","label":"Réglage d''un outil existant","color":"#64748b"},{"id":"document","label":"Document ou modèle unique","color":"#059669"},{"id":"automatisation","label":"Automatisation simple","color":"#0284c7"},{"id":"workflow","label":"Workflow sans IA","color":"#0d9488"},{"id":"agent","label":"Nouvel agent IA","color":"#7c3aed"}]'::jsonb),
('contre','{"arrivee":{"objection":"Un formulaire d''annonce obligatoire suffirait peut-être, sans agent.","verif":"Les 4 annonces arrivent par mail, écrites librement, par 4 personnes différentes (mails 1, 4, 14, 21). Le délai de 10 jours est connu de tous (CR-1, mail 7) et pourtant dépassé : le problème est autant le calcul des échéances que la saisie.","conclusion":"Irritant maintenu, confiance moyenne. Recommandation : un formulaire (sans IA) ET l''agent pour les annonces qui continueront d''arriver par mail. À confirmer avec la RH.","ok":true},"doc":{"objection":"Un agent de recherche documentaire aiderait-il les arrivants à trouver le bon livret ?","verif":"Le problème n''est pas de trouver : il existe 3 livrets, 2 formulaires de compte et 2 textes sur le télétravail qui se contredisent (mails 3, 9, 13, CR-4).","conclusion":"Pas d''agent. Une page de référence unique, une version par document. Un agent masquerait le désordre au lieu de le supprimer.","ok":true}}'::jsonb),
('questions_contre','["Le mail est-il vraiment ce que la détection affirme (une annonce, une question, un renvoi) ?","L''information a-t-elle pu circuler ailleurs (téléphone, réunion) ?","L''irritant tient-il au processus, ou à un cas isolé ?","Les sources citées disent-elles bien ce que la détection affirme ?","La réponse proposée est-elle la plus simple ? Un document ou un réglage suffirait-il ?"]'::jsonb),
('spec_integration','[["Irritant détecté","Les arrivées sont mal préparées : 3 annonces incomplètes sur 3, demandes au support parties après les délais connus, 3 arrivants sur 3 sans poste ou sans accès complet le premier jour. Sources : mails 1, 4, 6, 7, 11, 12, 14, 16, 20 ; CR-1 à CR-4. Confiance moyenne après contre-analyse. Interprétation des signaux, pas une cause prouvée. Données fictives."],["Besoin métier","« Quand un manager m''annonce une arrivée, je veux savoir tout de suite ce qui manque et ce qui est déjà en retard, et avoir les messages prêts. » (administration du personnel)"],["Utilisateurs","L''administration du personnel (valide et envoie), le manager (reçoit la demande d''informations), l''informatique et les services généraux (reçoivent les demandes), le HRBP (propriétaire du processus)."],["Entrées","Mails de la boîte RH qui annoncent une arrivée ; checklist d''intégration de référence et délais par étape (Notion)."],["Sorties","Une fiche d''arrivée dans Notion (étapes, échéances, statut) ; 3 brouillons : au manager (informations manquantes), à l''informatique (poste, comptes, habilitation), aux services généraux (badge, place) ; une alerte si un délai est déjà dépassé, avec une solution de repli."],["Workflow","1. Un mail annonce une arrivée. 2. L''agent extrait date, poste, manager, lieu, matériel, accès. 3. Il compare à la checklist et liste ce qui manque. 4. Il calcule le rétro-planning et repère les délais dépassés. 5. Il crée la fiche d''arrivée et prépare les 3 brouillons. 6. La RH relit, modifie, envoie. 7. Cinq jours avant l''arrivée, l''agent signale les étapes non faites."],["Niveau d''autonomie","Préparer. L''agent n''envoie rien : une mauvaise date ou un message mal formulé peut coûter un premier jour. Le passage à « agir » (envoi automatique des demandes standard à l''informatique) n''est envisageable qu''après une période de mesure, sur décision du HRBP."],["Permissions et risques","Lecture de la boîte RH ; écriture de la fiche d''arrivée et des brouillons. Jamais : lire les pièces administratives, lire un mail classé confidentiel, envoyer un mail, évaluer une personne. Risque : données personnelles du futur employé. Parade : l''agent ne traite que l''annonce (nom, date, poste), jamais le dossier. Risque : faux positif. Parade : la RH valide chaque fiche."],["Agent proposé","Nouvel agent, branché sur la boîte RH (MCP Thunderbird) et sur Notion (checklist, fiches d''arrivée). En complément, sans IA : un formulaire d''annonce pour les managers qui préfèrent l''utiliser."],["Critères d''acceptation","Sur le jeu de données : les 4 annonces reconnues (mails 1, 4, 14, 21) ; les informations manquantes listées sans erreur ; le délai dépassé signalé pour le mail 21 ; l''habilitation de l''arrivant cybersécurité repérée dès le mail 14 ; le mail 17 jamais analysé ; aucun mail envoyé."],["Gain attendu et indicateur","Indicateur principal : part des arrivants avec poste et accès prêts le premier jour. Secondaire : nombre de mails échangés par arrivée avant le premier jour. Valeurs : à mesurer, avant et après."]]'::jsonb),
('gen_steps','["Lecture de l''irritant validé et de ses sources","Application du modèle en 11 rubriques","Choix du niveau d''autonomie le plus bas qui suffit","Vérification : validation humaine, aucun envoi, aucun chiffre inventé, aucune donnée individuelle"]'::jsonb),
('prompt_gen','"Tu es analyste métier RH. À partir de l''irritant ci-dessous et de ses sources, rédige une spécification selon ce modèle : Irritant détecté, Besoin métier, Utilisateurs, Entrées, Sorties, Workflow, Niveau d''autonomie, Permissions et risques, Agent proposé, Critères d''acceptation, Gain attendu et indicateur.\n\nRègles :\n- Propose d''abord la réponse la plus simple : un réglage, un document ou un workflow sans IA avant un agent.\n- Le workflow contient toujours une étape de validation humaine.\n- Rien n''est envoyé sans validation.\n- Aucune donnée individuelle : l''irritant décrit une étape du processus, jamais une personne.\n- Les mails confidentiels et les pièces administratives ne sont jamais lus.\n- N''invente aucun chiffre : si un gain n''est pas chiffrable, écris-le.\n- Cite les sources (numéros de mails, comptes rendus)."'::jsonb),
('agent_steps','[{"label":"Lecture du mail 21","detail":"« Lucas Fabre nous rejoint lundi prochain comme consultant data. Merci de faire le nécessaire ! »","outil":"MCP Thunderbird"},{"label":"Reconnaissance d''une annonce d''arrivée","detail":"Nom, poste (consultant data), date (lundi prochain), manager (expéditrice).","outil":"Claude"},{"label":"Comparaison avec la checklist","detail":"Manquent 3 informations sur 6 : lieu du premier jour, matériel, accès particuliers.","outil":"MCP Notion"},{"label":"Calcul du rétro-planning","detail":"Poste : 10 jours ouvrés, délai déjà dépassé. Badge : 3 jours, possible si demandé aujourd''hui. Repli proposé : PC de secours.","outil":"Claude"},{"label":"Rapprochement avec l''historique","detail":"Même schéma pour les 3 arrivées précédentes, quel que soit le manager : c''est le processus qui est en cause, pas une personne.","outil":"Claude"},{"label":"Contre-analyse","detail":"Les informations ont-elles été données par téléphone ? Aucune trace écrite : l''agent pose la question au lieu de supposer.","outil":"Claude"},{"label":"Fiche d''arrivée et 3 brouillons","detail":"Fiche créée dans Notion. Brouillons : à la manager, à l''informatique, aux services généraux.","outil":"MCP Notion"},{"label":"La RH relit et envoie","detail":"Camille valide, modifie ou ignore. L''agent n''envoie rien lui-même.","outil":"Humain","human":true}]'::jsonb),
('roles','[{"id":"collab","nom":"Camille","role":"Administration du personnel","persona":"Collaborateur","tabs":[["arrivees","Arrivées à préparer"],["registre","Ce que l''assistant repère dans mon activité"]]},{"id":"manager","nom":"Isabelle","role":"Manager BU Data","persona":"Manager","tabs":[["mesarrivees","Mes arrivées"],["equipe","Irritants qui touchent mon équipe"]]},{"id":"hrbp","nom":"Julien","role":"HRBP","persona":"HRBP","tabs":[["registre","Registre RH"],["orienter","Valider et orienter"],["spec","Spécifications"],["suivre","Suivi des réponses"]]},{"id":"dir","nom":"Direction","role":"Direction d''agence","persona":"Dirigeants","tabs":[["tableau","Tableau de bord"]]},{"id":"futur","nom":"Lucas","role":"Futur employé","persona":"Futur employé","tabs":[["futur","Ce qu''il reçoit"]]}]'::jsonb),
('arrivees_passees','[{"nom":"Hugo Lefèvre","poste":"Consultant test logiciel","date":"J15","etat":"Premier jour sans poste (mail 12)"},{"nom":"Sarah Benmoussa","poste":"Consultante PMO","date":"J15","etat":"Premier jour sans poste (mail 12)"},{"nom":"Antoine Roche","poste":"Consultant cybersécurité","date":"J22","etat":"PC de secours ; habilitation et outil des temps manquants (mail 20)"}]'::jsonb),
('ident','{"collab":["Camille Rousseau","Chargée d''administration du personnel"],"manager":["Isabelle Moreau","Manager BU Data"],"hrbp":["Julien Mercier","HRBP de l''agence"],"dir":["Direction","Direction d''agence"],"futur":["Lucas Fabre","Futur employé, consultant data"]}'::jsonb),
('irr_manager','[["arrivee","L''annonce de l''arrivée est l''étape du manager : c''est elle qui déclenche le poste, les comptes, l''habilitation et le badge."],["boucle","Les annonces d''arrivée partent sans les services généraux : le badge et la place sont demandés trop tard."],["actions","Au comité où les managers sont présents, des actions sur l''intégration sont décidées sans responsable ni échéance."]]'::jsonb),
('indicateurs','{"arrivee":"Part des arrivants avec poste et accès prêts le premier jour","doc":"Questions « lequel / où est » reçues par mois","questions":"Questions reçues déjà couvertes par la FAQ","actions":"Actions reportées plus de 2 fois","boucle":"Arrivées signalées à temps aux services généraux","pieces":"Renvois de pièces par arrivée"}'::jsonb),
('confiance','[["✓","Sources lues : la boîte partagée « RH – Administration du personnel » et les comptes rendus, autorisées par Scalian. Le dossier partagé : source à confirmer."],["✕","Jamais de visios, d''enregistrements ni de tickets. Jamais les pièces administratives jointes."],["✕","Un mail confidentiel (santé, conflit, situation personnelle) est écarté sans être analysé."],["✕","Aucun irritant n''est attribué à une personne : le registre décrit des étapes du processus."],["✓","Le collaborateur et le manager concernés voient d''abord l''irritant et peuvent le contester ; le HRBP valide."],["✓","Chaque irritant est une interprétation des signaux, avec ses sources, pas une cause prouvée."]]'::jsonb),
('confiance_manager','[["✓","Les irritants du processus d''intégration dont une étape dépend du manager."],["✓","Votre avis (confirmer ou contester) est transmis au HRBP, qui décide."],["✕","Aucun nom de collègue, aucun mail individuel, aucune comparaison entre managers ou entre équipes."],["✕","Les irritants propres à l''administration du personnel restent visibles par la RH et le HRBP."]]'::jsonb),
('futur_mail','["Bienvenue Lucas ! Vous arrivez lundi : Isabelle Moreau vous accueille.","Votre poste et votre badge seront prêts à votre arrivée.","Réponses aux questions fréquentes : télétravail, mutuelle, notes de frais (lien).","Tous les documents d''accueil, dans leur version en vigueur, lisibles dès maintenant (lien).","Chaque envoi de pièces reçoit une confirmation automatique."]'::jsonb)
